mapper.select:
select t.factory_id factoryId, t.factory_name factoryName, t.bean_impl beanImpl, t.remark, t.create_time createTime, t.status_cd statusCd, lmfs.spec_id specId, lmfs.factory_id factoryId1, lmfs.spec_name specName, lmfs.create_time createTime1, lmfs.status_cd statusCd1, lmfs.remark remark1 from lamp_machine_factory t left join lamp_machine_factory_spec lmfs on t.factory_id = lmfs.factory_id and lmfs.status_cd = '0' where 1 =1
and t.factory_id like concat('%', #{factoryId}, '%')
and t.factory_name like concat('%', #{factoryName}, '%')
and t.remark= #{remark}
and t.status_cd= #{statusCd}
and t.bean_impl like concat('%', #{beanImpl}, '%')
order by t.create_time desc
limit #{page}, #{row}

